import React, { useState, useEffect } from 'react';

const COLORS = {
  bg: '#020617', card: '#0f172a', accent: '#38bdf8', 
  gold: '#fbbf24', text: '#f8fafc', muted: '#94a3b8', 
  border: '#1e293b', success: '#22c55e', danger: '#ef4444'
};

export default function App() {
  const [tab, setTab] = useState('dashboard');
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('juris_v7_data');
    return salvo ? JSON.parse(salvo) : [];
  });

  const [novoProc, setNovoProc] = useState({ 
    cliente: '', numero: '', valor: '', data: '', status: 'Ativo', area: 'Cível' 
  });

  useEffect(() => {
    localStorage.setItem('juris_v7_data', JSON.stringify(processos));
  }, [processos]);

  const calcularPrazoFinal = (dataInicio) => {
    if (!dataInicio) return null;
    let data = new Date(dataInicio + 'T00:00:00');
    let diasContados = 0;
    while (diasContados < 15) {
      data.setDate(data.getDate() + 1);
      if (data.getDay() !== 0 && data.getDay() !== 6) diasContados++;
    }
    return data;
  };

  const addProcesso = () => {
    if (!novoProc.cliente || !novoProc.valor) return alert("Dados incompletos!");
    setProcessos([...processos, { ...novoProc, id: Date.now() }]);
    setNovoProc({ cliente: '', numero: '', valor: '', data: '', status: 'Ativo', area: 'Cível' });
    setTab('dashboard');
  };

  // Função para imprimir o relatório atual
  const imprimirRelatorio = () => {
    window.print();
  };

  const totalHonorarios = processos.reduce((a, b) => a + Number(b.valor), 0);

  return (
    <div style={s.app}>
      <aside style={{...s.sidebar, display: tab === 'print' ? 'none' : 'flex'}} className="no-print">
        <div style={s.brand}><div style={s.brandIcon}>J</div> JurisPRO</div>
        <nav style={s.nav}>
          <div style={s.navLink(tab === 'dashboard')} onClick={() => setTab('dashboard')}>📊 Dashboard</div>
          <div style={s.navLink(tab === 'agenda')} onClick={() => setTab('agenda')}>📅 Prazos Fatais</div>
          <div style={s.navLink(tab === 'novo')} onClick={() => setTab('novo')}>➕ Novo Registro</div>
        </nav>
        <div style={s.licenseCard}>
          <div style={{fontSize: '11px', color: COLORS.gold}}>RODRIGO ADVOCACIA</div>
          <div style={{fontSize: '10px', marginTop: '5px'}}>ID: JP-2026-X89</div>
        </div>
      </aside>

      <main style={s.content}>
        <header style={{...s.header, display: tab === 'print' ? 'none' : 'flex'}} className="no-print">
          <div>
            <h2 style={{margin: 0}}>Gestão de Alta Performance</h2>
            <p style={{color: COLORS.muted, fontSize: '14px'}}>Controlo financeiro e de prazos do escritório.</p>
          </div>
          <button style={s.btnExport} onClick={imprimirRelatorio}>📄 GERAR RELATÓRIO PDF</button>
        </header>

        {tab === 'dashboard' && (
          <div style={s.grid}>
            <StatCard label="Patrimônio em Carteira" value={`R$ ${totalHonorarios.toLocaleString()}`} color={COLORS.success} />
            <StatCard label="Processos Monitorados" value={processos.length} color={COLORS.accent} />
            <StatCard label="Taxa de Eficiência" value="100%" color={COLORS.gold} />

            <div style={{...s.card, gridColumn: 'span 3'}}>
              <h3 style={{marginTop: 0}}>Resumo Geral de Atividades</h3>
              <table style={s.table}>
                <thead>
                  <tr>
                    <th style={s.th}>CLIENTE</th>
                    <th style={s.th}>ÁREA</th>
                    <th style={s.th}>VALOR ACORDADO</th>
                    <th style={s.th}>VENCIMENTO (CPC)</th>
                  </tr>
                </thead>
                <tbody>
                  {processos.map(p => (
                    <tr key={p.id}>
                      <td style={s.td}><strong>{p.cliente}</strong></td>
                      <td style={s.td}>{p.area}</td>
                      <td style={s.td}>R$ {Number(p.valor).toLocaleString()}</td>
                      <td style={s.td}>
                        <span style={s.deadlineBadge}>{p.data ? calcularPrazoFinal(p.data).toLocaleDateString() : '---'}</span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {tab === 'novo' && (
          <div style={{...s.card, maxWidth: '500px', margin: '0 auto'}}>
            <h3 style={{marginTop: 0, color: COLORS.accent}}>➕ Novo Cadastro</h3>
            <label style={s.label}>Cliente</label>
            <input style={s.input} value={novoProc.cliente} onChange={e => setNovoProc({...novoProc, cliente: e.target.value})} />
            <label style={s.label}>Honorários (R$)</label>
            <input style={s.input} type="number" value={novoProc.valor} onChange={e => setNovoProc({...novoProc, valor: e.target.value})} />
            <label style={s.label}>Data da Intimação</label>
            <input style={s.input} type="date" value={novoProc.data} onChange={e => setNovoProc({...novoProc, data: e.target.value})} />
            <button style={s.btnMain} onClick={addProcesso}>CONFIRMAR REGISTRO</button>
          </div>
        )}
      </main>

      <style>{`
        @media print {
          body { background: white !important; color: black !important; }
          .no-print { display: none !important; }
          main { padding: 0 !important; }
          div[style*="background-color: rgb(15, 23, 42)"] { background: white !important; border: 1px solid #ccc !important; box-shadow: none !important; }
          table { color: black !important; border: 1px solid #eee !important; }
          th { color: #666 !important; }
          h2, h3, span { color: black !important; }
        }
      `}</style>
    </div>
  );
}

const StatCard = ({label, value, color}) => (
